from contextlib import ExitStack

class Step:
    def __init__(self, n):
        self.n = n
    def __enter__(self):
        print("вход", self.n)
        return self.n
    def __exit__(self, *exc):
        print("выход", self.n)

with ExitStack() as stack:
    nums = [stack.enter_context(Step(i)) for i in range(1, 3)]
    print("внутри", nums)

from contextlib import contextmanager

@contextmanager
def transaction(log):
    log.append("begin")
    try:
        yield
    except ValueError:
        log.append("rollback")
        raise

log = []
try:
    with transaction(log):
        raise ValueError("плохие данные")
except ValueError:
    log.append("ошибка дошла")
print(log)

