def pair_sum(nums, target):
    lo, hi = 0, len(nums) - 1
    steps = 0
    while lo < hi:
        steps += 1
        s = nums[lo] + nums[hi]
        if s == target:
            return nums[lo], nums[hi], steps
        if s < target:
            lo += 1
        else:
            hi -= 1
    return None

