def has_dup_slow(items):
    steps = 0
    for i in range(len(items)):
        for j in range(i + 1, len(items)):
            steps += 1
            if items[i] == items[j]:
                return True, steps
    return False, steps

def has_dup_fast(items):
    seen = set()
    for steps, x in enumerate(items, 1):
        if x in seen:
            return True, steps
        seen.add(x)
    return False, len(items)

